const legacyPulse = text => /เรื่อง “|สรุปเรื่อง |ประเด็น .*ยังทำให้|จับตา .*ต่อ|บรรยากาศ .*แบบหมดรูป|จุดชมวิวเรื่อง/u.test(String(text || ''));
export function feedViewModel(page) { return Object.freeze((page?.items || []).filter(post => !legacyPulse(post.text)).map(post => Object.freeze({ key: post.postId, postId: post.postId, authorAccountId: post.authorAccountId, text: post.text, audience: post.audience.kind, storyTimeRef: post.storyTimeRef, assetRefs: post.assetRefs, likeCount: Number(post.likeCount || 0), commentCount: Number(post.commentCount || 0), commentPreview: Object.freeze([...(post.commentPreview || [])]) }))); }
